const body = $input.first().json.body || $input.first().json;
const owner = String(body.owner || '').trim();
const repo  = String(body.repo  || '').trim();
const filePath = String(body.filePath || 'Dockerfile').trim();
const ref = String(body.ref || 'main').trim();
if (!owner || !repo) return [{ json: { error:'INVALID_INPUT', message:'owner et repo sont requis' } }];
return [{ json: { owner, repo, filePath, ref } }];

const gh = $input.first().json;
let decoded = '';
if (typeof gh.content === 'string' && gh.encoding === 'base64') {
  try { decoded = Buffer.from(gh.content.replace(/\n/g,''), 'base64').toString('utf-8'); } catch(e) {}
} else if (typeof gh.content === 'string') {
  decoded = gh.content;                          // déjà décodé par le node n8n
} else if (typeof gh.data === 'string') {
  decoded = gh.data;
}
if (!decoded || decoded.length < 10) {
  return [{ json: { success:false, error:'EMPTY_FILE', message:'Dockerfile vide ou introuvable — collez-le manuellement' } }];
}
return [{ json: { success:true, content:decoded, filePath:$('Prepare - Fetch Body').first().json.filePath, sha:gh.sha||'', source:'github' } }];

const j = $input.first().json;
let message = j.message || 'Fichier introuvable sur le dépôt';
if (j.error === undefined && j.status === undefined) message = 'Dockerfile introuvable — vérifiez owner/repo/branche/chemin ou collez-le manuellement';
return [{ json: { success:false, error:j.error||'FETCH_ERROR', message } }];

const body = $input.first().json.body || $input.first().json;
const dockerfile = String(body.dockerfile || '').trim();
const pomXml = String(body.pomXml || '').trim();
const appConfig = String(body.appConfig || '').trim();
const projectName = body.projectName || 'projet';
const context = body.context || {};
if (!dockerfile || dockerfile.length < 20) return [{ json: { error: 'INVALID_INPUT', message: 'Dockerfile vide ou trop court (min 20 caractères)' } }];
if (dockerfile.length > 30000) return [{ json: { error: 'TOO_LARGE', message: 'Dockerfile trop volumineux (max 30 Ko)' } }];

const numberLines = (text) => text.split('\n').map((l, i) => `${i + 1}: ${l}`).join('\n');
const dockerfileNumbered = numberLines(dockerfile);

const systemPrompt = `Tu es un expert Docker et sécurité des conteneurs (15 ans d'expérience), spécialisé DevSecOps.
Ta mission : analyser un Dockerfile et détecter des problèmes dans 2 catégories, SANS réécrire le fichier (la remédiation est un traitement séparé, futur).
Réponds UNIQUEMENT en JSON valide — pas de markdown, pas de backticks. Commence par { et termine par }.
LANGUE : tous les textes en FRANÇAIS professionnel.
IMPORTANT — PÉRIMÈTRE : un contrôle DÉTERMINISTE séparé (code, pas toi) gère déjà :
- la cohérence de version JDK entre le Dockerfile et le pom.xml (catégorie CAT-JDK) — n'émets JAMAIS de finding CAT-JDK, ce n'est pas ton rôle ;
- l'obsolescence de version JDK de l'image de base (JDK 6/7/8) et l'absence de tag pinné (":latest" ou tag absent) — n'émets JAMAIS de finding sur CES DEUX points précis pour l'image de base, ils sont déjà couverts avec certitude par le code.
IMPORTANT — TRIVY : un scanner CVE séparé (Trivy) liste déjà les vulnérabilités connues des paquets de l'image (CVE, CVSS, package). Ce n'est PAS ton rôle, pour AUCUNE catégorie : n'énumère JAMAIS un identifiant CVE ni une vulnérabilité de paquet précise. Tu juges la CONCEPTION et les pratiques du Dockerfile, jamais son contenu scanné.
IMPORTANT — PÉRIMÈTRE CAT-SECURITY : un contrôle DÉTERMINISTE séparé (code, pas toi) gère déjà l'absence d'instruction USER non-root, l'absence de HEALTHCHECK, les secrets/tokens/mots de passe en dur (ENV/ARG avec une valeur littérale) ET l'usage d'ADD pour un fichier local (au lieu de COPY) dans le Dockerfile — n'émets JAMAIS de finding sur CES QUATRE points précis, ils sont déjà couverts avec certitude par le code.
CATEGORIES À DETECTER (chaque finding appartient à UNE SEULE catégorie) :
1. CAT-IMAGE (uniquement les aspects NON couverts par le contrôle déterministe ci-dessus, jamais un CVE) : variante inadaptée (ex : image ":jdk" complète utilisée en étape finale alors qu'une variante ":jre" suffit pour exécuter un .jar déjà compilé — taille et surface d'attaque inutiles), image de base lourde ou non officielle quand une alternative plus légère/officielle existe pour le même usage, autres mauvaises pratiques de choix d'image de base (absence de build multi-stage, absence d'épinglage par digest SHA256, etc). Pour CHAQUE finding CAT-IMAGE, "suggestion" DOIT proposer une image de base cible concrète et réaliste (ex : "remplacer par eclipse-temurin:17-jre-jammy") quand un remplacement d'image est pertinent — jamais un conseil vague type "utilisez une meilleure image".
2. CAT-SECURITY (uniquement les aspects NON couverts par le contrôle déterministe ci-dessus, jamais un CVE) : apt-get/apk install sans nettoyage (absence de --no-install-recommends, absence de nettoyage du cache type 'apt-get clean && rm -rf /var/lib/apt/lists/*') augmentant surface d'attaque et poids inutilement, autres mauvaises pratiques de sécurité contextuelles du Dockerfile non listées ci-dessus (jugement au cas par cas). Pour CHAQUE finding CAT-SECURITY, "suggestion" DOIT proposer une correction concrète et directement applicable (ex : la commande exacte à ajouter/modifier) — jamais un conseil vague type "améliorez la sécurité".
RÈGLES DE PRÉCISION :
- "ligne" doit être le numéro de ligne EXACT dans le Dockerfile numéroté fourni ci-dessous (jamais une estimation). Pour une absence (USER, HEALTHCHECK), donne la ligne après laquelle l'ajouter (ex : la dernière ligne du fichier).
- Ne remonte QUE des findings réels, visibles dans le contenu fourni — jamais d'hypothèse non vérifiable.
- Une seule catégorie par finding, pas de doublon entre catégories pour le même problème.
FORMAT EXACT :
{"score":<0-100 du Dockerfile>,"summary":"<3-4 phrases ; le score et le résumé tiennent compte de l'ensemble des problèmes même ceux détectés par le contrôle déterministe, mentionnés séparément>","issues":[{"id":"DF-1","category":"CAT-IMAGE|CAT-SECURITY","severity":"CRITIQUE|ELEVE|MOYEN|FAIBLE","ligne":<numéro de ligne entier>,"description":"<1-2 phrases décrivant le problème>","suggestion":"<action concrète à faire>"}],"confidence":<0.0-1.0>}`;

const userContent = `Analyse ce Dockerfile du projet "${projectName}".
${context.notes ? `Notes : ${context.notes}\n` : ''}
DOCKERFILE (numéroté) :
\`\`\`dockerfile
${dockerfileNumbered}
\`\`\``;

return [{ json: {
  apiBody: { model: 'claude-sonnet-4-6', max_tokens: 4000, temperature: 0, system: systemPrompt, messages: [{ role: 'user', content: userContent }] },
  projectName,
  dockerfile,
  pomXml,
  appConfig,
} }];

const response = $input.first().json;
const fail = (msg, raw) => [{ json: { success:false, error:'PARSE_ERROR', message:msg, raw:String(raw||'').substring(0,800) } }];
if (response.error) return [{ json: { success:false, error:response.error, message:response.message } }];
const content = response.content?.[0]?.text || '';
if (!content) return fail("Réponse vide de l'agent", JSON.stringify(response).substring(0,300));
let clean = content.replace(/```json\s*/gi,'').replace(/```\s*/gi,'').trim();
const s = clean.indexOf('{'), e = clean.lastIndexOf('}');
if (s === -1 || e === -1) return fail('Aucun JSON trouvé', clean);
try {
  const p = JSON.parse(clean.substring(s, e+1));

  // ── Findings déterministes (Runtime Coherence Checker RC-1..N + sous-
  // partie CAT-IMAGE) — calculés par "Runtime Coherence Checker", en amont
  // de l'appel LLM, jamais par le LLM lui-même. Même philosophie que le
  // gate de sélection WF4 : ce qui doit être EXACT et reproductible passe
  // par du code, pas par un prompt.
  let deterministic = { findings: [], runtimeCoherence: { checks: {}, notes: [] } };
  try { deterministic = $('Runtime Coherence Checker').first().json.deterministicChecks || deterministic; } catch (_) {}

  // Issues LLM : seules CAT-IMAGE et CAT-SECURITY sont légitimes — un
  // CAT-JDK émis malgré la consigne du prompt est un défaut de l'agent,
  // pas une donnée fiable, donc rejeté ici (defense in depth).
  const LLM_VALID_CAT = new Set(['CAT-IMAGE','CAT-SECURITY']);
  const llmIssues = (Array.isArray(p.issues) ? p.issues : []).filter(i => LLM_VALID_CAT.has(i.category));

  const allIssues = [...deterministic.findings, ...llmIssues];
  const o = { CRITIQUE:0, ELEVE:1, MOYEN:2, FAIBLE:3 };
  allIssues.sort((a,b)=>(o[a.severity]??9)-(o[b.severity]??9));

  return [{ json: {
    success:true,
    analyzedAt:new Date().toISOString(),
    score: p.score,
    summary: p.summary,
    confidence: p.confidence,
    issues: allIssues,
    runtimeCoherence: deterministic.runtimeCoherence,
  } }];
} catch (err) { return fail('JSON invalide : '+err.message, clean); }

return [{ json: {
  jobId: $('Webhook - Dockerfile Optimize').first().json.body.jobId,
  status: 'error',
  reason: "Agent IA a \u00e9chou\u00e9 (rate limit / erreur API Anthropic)",
  detail: ($json.error && $json.error.message) ? $json.error.message : (String($json.error) || 'Erreur inconnue'),
}}];

return [{ json: {
  jobId: $('Webhook - Dockerfile Optimize').first().json.body.jobId,
  status: 'error',
  reason: "R\u00e9ponse de l'agent illisible (\u00e9chec de parsing JSON)",
  detail: ($json.error && $json.error.message) ? $json.error.message : (String($json.error) || 'Erreur de parsing inconnue'),
}}];

// ─────────────────────────────────────────────────────────────────────────
// RUNTIME COHERENCE CHECKER — patron extensible.
//
// Contrat d'un module de check RC-N (objet simple, aucune classe requise) :
//   {
//     id, name, category,                      // identité + catégorie de finding
//     extractDockerfile(dockerfile) -> { value, determined, reason, line, ...détails },
//     extractProject(projectFiles)  -> { value, determined, reason, source, ...détails },
//     describe(dockerfileVal, projectVal) -> { severity, description, suggestion },
//   }
// extractDockerfile/extractProject retournent TOUJOURS determined:false plutôt
// que de deviner (tag latest, valeur héritée d'un <parent> Maven non résolue,
// pattern non reconnu, fichier absent, etc.).
//
// Le moteur runCoherenceChecks() applique CE MÊME contrat à chaque module,
// sans connaître son contenu métier : extraction des 2 côtés, puis 3 états
// possibles — jamais 2 :
//   1. déterminées + différentes → finding (via describe())
//   2. déterminées + identiques → RAS, rien n'est émis
//   3. au moins une indéterminée → jamais de finding, au plus une note
// Ajouter RC-2/RC-3 = pousser un nouvel objet dans CHECKS. runCoherenceChecks
// ne change JAMAIS.
// ─────────────────────────────────────────────────────────────────────────
function runCoherenceChecks(checks, ctx) {
  const findings = [];
  const notes = [];
  const details = {};

  for (const check of checks) {
    const a = check.extractDockerfile(ctx.dockerfile);
    const b = check.extractProject(ctx.projectFiles);
    const bothDetermined = a.determined && b.determined;
    const mismatch = bothDetermined && a.value !== b.value;

    details[check.id] = { dockerfile: a, project: b, comparable: bothDetermined, mismatch };

    if (mismatch) {
      const d = check.describe(a, b);
      findings.push({
        id: `DF-${check.id}`,
        category: check.category,
        severity: d.severity,
        ligne: a.line ?? null,
        description: d.description,
        suggestion: d.suggestion,
        deterministic: true,
      });
    } else if (!bothDetermined) {
      const parts = [];
      if (!a.determined) parts.push(`Dockerfile : ${a.reason}`);
      if (!b.determined) parts.push(`${check.projectSource || 'fichier projet'} : ${b.reason}`);
      const note = `[${check.id}] ${check.name} — non déterminable avec certitude : ${parts.join(' ; ')}. Vérification manuelle recommandée ; aucune incohérence supposée.`;
      notes.push({ id: check.id, name: check.name, note });
      details[check.id].note = note;
    }
    // cas 2 (déterminées + identiques) : rien à ajouter, RAS silencieux.
  }

  return { findings, notes, details };
}

// ── RC-1 : cohérence version JDK (Dockerfile FROM ↔ pom.xml) ──────────────
const RC1_JDK_VERSION = {
  id: 'RC-1',
  name: 'Cohérence version JDK',
  category: 'CAT-JDK',
  projectSource: 'pom.xml',

  // Image finale = dernière instruction FROM (couvre le multi-stage). Familles
  // reconnues : eclipse-temurin, openjdk, adoptopenjdk, amazoncorretto,
  // zulu-openjdk — variantes -jdk/-jre/-alpine/-slim toutes supportées via le
  // numéro en tête du tag. Hors de cette liste, ou tag latest/absent/non
  // numérique → determined:false, jamais une supposition.
  extractDockerfile(dockerfile) {
    const KNOWN_JDK_IMAGES = /(eclipse-temurin|openjdk|adoptopenjdk|amazoncorretto|zulu-openjdk|azul\/zulu-openjdk)/i;
    const text = String(dockerfile || '');
    const lines = text.split('\n');
    const fromIdx = [];
    lines.forEach((l, i) => { if (/^\s*FROM\s+\S+/i.test(l)) fromIdx.push(i); });
    if (fromIdx.length === 0) {
      return { value: null, determined: false, reason: 'aucune instruction FROM trouvée', line: null, raw: null, image: null, tag: null };
    }
    const lastIdx = fromIdx[fromIdx.length - 1];
    const ref = lines[lastIdx].replace(/^\s*FROM\s+/i, '').trim().split(/\s+/)[0]; // ignore "AS builder"
    const line = lastIdx + 1;

    const afterLastSlash = ref.split('/').pop();
    let image = afterLastSlash, tag = null;
    if (afterLastSlash.includes(':')) {
      const idx = afterLastSlash.indexOf(':');
      image = afterLastSlash.slice(0, idx);
      tag = afterLastSlash.slice(idx + 1);
    }
    const fullImageName = ref.split(':')[0]; // pour matcher azul/zulu-openjdk (contient un '/')

    if (!KNOWN_JDK_IMAGES.test(fullImageName)) {
      return { value: null, determined: false, reason: 'image de base non reconnue comme JDK/JRE (parseur limité aux familles connues : eclipse-temurin, openjdk, adoptopenjdk, amazoncorretto, zulu-openjdk)', line, raw: ref, image, tag };
    }
    if (!tag || tag === 'latest') {
      return { value: null, determined: false, reason: tag === 'latest' ? 'tag "latest" non pinné — version non déterminable avec certitude' : 'aucun tag — version non déterminable (latest implicite)', line, raw: ref, image, tag: tag || null };
    }
    const m = /^(\d+)/.exec(tag); // couvre "8", "8-jdk", "11-jre-slim", "17-jdk-alpine", "8u282-b08-jdk"
    if (!m) {
      return { value: null, determined: false, reason: `tag "${tag}" ne débute pas par un numéro de version JDK reconnu`, line, raw: ref, image, tag };
    }
    return { value: m[1], determined: true, reason: null, line, raw: ref, image, tag };
  },

  // Ordre standard Maven : maven.compiler.release > .target > java.version.
  // Ne résout JAMAIS un <parent> pour deviner sa valeur héritée — si aucune
  // des 3 propriétés n'est déclarée EXPLICITEMENT dans ce pom.xml, indéterminé.
  extractProject(projectFiles) {
    const xml = projectFiles && projectFiles.pomXml;
    if (!xml) return { value: null, determined: false, reason: 'pom.xml absent', source: null };
    const patterns = [
      { re: /<maven\.compiler\.release>\s*(\d+)\s*<\/maven\.compiler\.release>/i, src: 'maven.compiler.release' },
      { re: /<maven\.compiler\.target>\s*(\d+)\s*<\/maven\.compiler\.target>/i, src: 'maven.compiler.target' },
      { re: /<java\.version>\s*(\d+)\s*<\/java\.version>/i, src: 'java.version' },
    ];
    for (const p of patterns) {
      const m = p.re.exec(xml);
      if (m) return { value: m[1], determined: true, reason: null, source: p.src };
    }
    const hasParent = /<parent>/i.test(xml);
    return {
      value: null, determined: false, source: null,
      reason: hasParent
        ? "aucune propriété maven.compiler.*/java.version déclarée explicitement — un <parent> Maven est présent mais sa valeur héritée n'est pas résolue (jamais devinée)"
        : 'aucune propriété maven.compiler.*/java.version trouvée dans ce pom.xml',
    };
  },

  describe(dockerfileVal, projectVal) {
    return {
      severity: 'CRITIQUE',
      description: `Incohérence JDK détectée par contrôle déterministe (RC-1) : l'image de base (${dockerfileVal.raw}) fournit le JDK ${dockerfileVal.value}, alors que le pom.xml cible Java ${projectVal.value} (propriété ${projectVal.source}).`,
      suggestion: `Aligner les deux : passer l'image de base à un JDK/JRE ${projectVal.value} (ex: ${dockerfileVal.image || 'eclipse-temurin'}:${projectVal.value}-jre-jammy), ou abaisser la cible du pom.xml à ${dockerfileVal.value} si la montée de version n'est pas voulue.`,
    };
  },
};

// ── RC-2 : cohérence port (Dockerfile EXPOSE ↔ application.properties/.yml server.port) ──
const RC2_PORT = {
  id: 'RC-2',
  name: 'Cohérence port (EXPOSE ↔ server.port)',
  category: 'CAT-PORT',
  projectSource: 'application.properties/.yml',

  extractDockerfile(dockerfile) {
    const text = String(dockerfile || '');
    const lines = text.split('\n');
    const fromIdx = [];
    lines.forEach((l, i) => { if (/^\s*FROM\s+\S+/i.test(l)) fromIdx.push(i); });
    const stageStart = fromIdx.length ? fromIdx[fromIdx.length - 1] : 0; // étape finale (multi-stage)
    const finalLines = lines.slice(stageStart);

    const ports = [];
    finalLines.forEach((l, i) => {
      const m = /^\s*EXPOSE\s+(.+)$/i.exec(l);
      if (!m) return;
      m[1].trim().split(/\s+/).forEach((tok) => {
        const pm = /^(\d+)(\/(tcp|udp))?$/i.exec(tok);
        if (pm) ports.push({ value: pm[1], line: stageStart + i + 1, raw: l.trim() });
      });
    });

    if (ports.length === 0) {
      return { value: null, determined: false, reason: "aucune instruction EXPOSE trouvée (dans l'étape finale)", line: null, raw: null };
    }
    const distinct = [...new Set(ports.map((p) => p.value))];
    if (distinct.length > 1) {
      return { value: null, determined: false, reason: `plusieurs ports EXPOSE distincts (${distinct.join(', ')}) — ambigu, comparaison non fiable`, line: ports[0].line, raw: ports.map((p) => p.raw).join(' | ') };
    }
    return { value: distinct[0], determined: true, reason: null, line: ports[0].line, raw: ports[0].raw };
  },

  extractProject(projectFiles) {
    const cfg = projectFiles && projectFiles.appConfig;
    if (!cfg) return { value: null, determined: false, reason: 'fichier de configuration applicatif absent (application.properties/.yml non trouvé)', source: null };
    let m = /^\s*server\.port\s*[:=]\s*(\d+)\s*$/im.exec(cfg);
    if (m) return { value: m[1], determined: true, reason: null, source: 'server.port (properties)' };
    m = /server:\s*\n(?:[^\n]*\n)*?\s*port:\s*(\d+)/im.exec(cfg);
    if (m) return { value: m[1], determined: true, reason: null, source: 'server.port (yaml)' };
    return { value: null, determined: false, reason: 'aucune propriété server.port trouvée dans le fichier de configuration', source: null };
  },

  describe(dockerfileVal, projectVal) {
    return {
      severity: 'ELEVE',
      description: `Incohérence de port détectée par contrôle déterministe (RC-2) : le Dockerfile expose le port ${dockerfileVal.value} (${dockerfileVal.raw}), alors que l'application est configurée pour écouter sur le port ${projectVal.value} (${projectVal.source}).`,
      suggestion: `Aligner les deux : soit changer EXPOSE ${dockerfileVal.value} en EXPOSE ${projectVal.value} dans le Dockerfile, soit changer server.port à ${dockerfileVal.value} dans la configuration applicative.`,
    };
  },
};

// ── RC-3 : cohérence artefact (Dockerfile COPY ↔ nom produit par le build Maven) ──
const RC3_ARTIFACT = {
  id: 'RC-3',
  name: 'Cohérence artefact (COPY ↔ artefact Maven)',
  category: 'CAT-ARTIFACT',
  projectSource: 'pom.xml',

  extractDockerfile(dockerfile) {
    const text = String(dockerfile || '');
    const lines = text.split('\n');
    const fromIdx = [];
    lines.forEach((l, i) => { if (/^\s*FROM\s+\S+/i.test(l)) fromIdx.push(i); });
    const stageStart = fromIdx.length ? fromIdx[fromIdx.length - 1] : 0;
    const finalLines = lines.slice(stageStart);

    // Dernière instruction COPY (pas --from=, celles-là copient entre stages,
    // pas depuis le contexte de build) dont la source pointe vers un .jar.
    let found = null;
    finalLines.forEach((l, i) => {
      const m = /^\s*COPY\s+(?!--from=)(\S+\.jar)\s+\S+/i.exec(l);
      if (m) found = { raw: l.trim(), src: m[1], line: stageStart + i + 1 };
    });

    if (!found) {
      return { value: null, determined: false, reason: "aucune instruction COPY vers un .jar trouvée (dans l'étape finale)", line: null, raw: null };
    }
    if (found.src.includes('*')) {
      return { value: null, determined: false, reason: `chemin COPY avec wildcard (${found.src}) — nom de fichier exact non déterminable statiquement, build indisponible pour vérification`, line: found.line, raw: found.raw };
    }
    const basename = found.src.split('/').pop();
    return { value: basename, determined: true, reason: null, line: found.line, raw: found.raw };
  },

  extractProject(projectFiles) {
    const xml = projectFiles && projectFiles.pomXml;
    if (!xml) return { value: null, determined: false, reason: 'pom.xml absent', source: null };

    // Exclut <parent>...</parent> (artifactId/version du PARENT, pas du
    // projet) ET tout ce qui suit <dependencies> (artifactId/version des
    // DÉPENDANCES) — ne garde que la section d'identité du projet lui-même.
    const withoutParent = xml.replace(/<parent>[\s\S]*?<\/parent>/i, '');
    const projectSection = withoutParent.split(/<dependencies>/i)[0];

    // <build><finalName> a priorité s'il est déclaré et littéral (pas de
    // placeholder ${...} non résolvable statiquement).
    const finalNameM = /<finalName>\s*([^<\s]+)\s*<\/finalName>/i.exec(xml);
    if (finalNameM) {
      const finalName = finalNameM[1];
      if (/\$\{/.test(finalName)) {
        return { value: null, determined: false, source: 'build.finalName', reason: `<finalName> utilise un placeholder non résolvable statiquement (${finalName}) — build indisponible pour vérification` };
      }
      return { value: `${finalName}.jar`, determined: true, reason: null, source: 'build.finalName' };
    }

    // Convention Maven standard : <artifactId>-<version>.jar
    const artifactIdM = /<artifactId>\s*([^<\s]+)\s*<\/artifactId>/i.exec(projectSection);
    const versionM = /<version>\s*([^<\s]+)\s*<\/version>/i.exec(projectSection);
    if (!artifactIdM || !versionM) {
      return { value: null, determined: false, source: null, reason: "artifactId et/ou version du projet non trouvés dans ce pom.xml — nom d'artefact non déterminable, build indisponible pour vérification" };
    }
    return { value: `${artifactIdM[1]}-${versionM[1]}.jar`, determined: true, reason: null, source: 'artifactId + version' };
  },

  describe(dockerfileVal, projectVal) {
    return {
      severity: 'CRITIQUE',
      description: `Incohérence d'artefact détectée par contrôle déterministe (RC-3) : le Dockerfile copie "${dockerfileVal.value}" (${dockerfileVal.raw}), alors que le build Maven produira "${projectVal.value}" (${projectVal.source}).`,
      suggestion: `Corriger le chemin COPY dans le Dockerfile pour qu'il pointe vers "${projectVal.value}", ou aligner artifactId/version/finalName du pom.xml sur le nom réellement produit.`,
    };
  },
};

// ─────────────────────────────────────────────────────────────────────────
// REGISTRE — pour ajouter un futur RC-N : définir un objet suivant le même
// contrat puis l'ajouter ici. runCoherenceChecks() ne change JAMAIS.
// ─────────────────────────────────────────────────────────────────────────
const CHECKS = [RC1_JDK_VERSION, RC2_PORT, RC3_ARTIFACT];

// ── Exécution ────────────────────────────────────────────────────────────
const item = $input.first().json;
const dockerfile = String(item.dockerfile || '');
const pomXml = String(item.pomXml || '');
const appConfig = String(item.appConfig || '');

const { findings: rcFindings, notes: rcNotes, details: rcDetails } =
  runCoherenceChecks(CHECKS, { dockerfile, projectFiles: { pomXml, appConfig } });

// ── CAT-IMAGE (règle déterministe hors patron RC — ne compare pas deux
// fichiers, juste une règle sur le Dockerfile seul) : obsolescence connue +
// tag non pinné. Réutilise l'extraction RC-1 pour éviter de re-parser FROM.
const OBSOLETE_JDK_VERSIONS = new Set(['6', '7', '8']);
const KNOWN_JDK_IMAGES = /(eclipse-temurin|openjdk|adoptopenjdk|amazoncorretto|zulu-openjdk|azul\/zulu-openjdk)/i;
const df = RC1_JDK_VERSION.extractDockerfile(dockerfile);

const imageFindings = [];
if (df.determined && OBSOLETE_JDK_VERSIONS.has(df.value)) {
  imageFindings.push({
    id: 'DF-IMG-JDK',
    category: 'CAT-IMAGE',
    severity: 'CRITIQUE',
    ligne: df.line,
    description: `Version JDK obsolète détectée par contrôle déterministe : ${df.raw} embarque le JDK ${df.value}, en fin de support étendu.`,
    suggestion: `Migrer vers une image basée sur un JDK/JRE LTS supporté (17 ou 21) — ex: ${df.image || 'eclipse-temurin'}:17-jre-jammy.`,
    deterministic: true,
  });
}
if (df.image && KNOWN_JDK_IMAGES.test(df.image) && (!df.tag || df.tag === 'latest')) {
  imageFindings.push({
    id: 'DF-IMG-PIN',
    category: 'CAT-IMAGE',
    severity: 'ELEVE',
    ligne: df.line,
    description: `Image de base non pinnée détectée par contrôle déterministe : ${df.raw} n'a pas de tag explicite ou utilise "latest", ce qui rend le build non reproductible.`,
    suggestion: `Épingler un tag de version explicite (idéalement avec digest SHA256) plutôt que "latest".`,
    deterministic: true,
  });
}

// ── CAT-SECURITY (déterministe, hors patron RC — même logique que le bloc
// CAT-IMAGE ci-dessus : règles sur le Dockerfile seul, pas de comparaison
// à un fichier projet) : USER absent, HEALTHCHECK absent, secret en dur.
// Scope volontairement limité à ces 3 faits nets — apt-get sans nettoyage et
// ADD vs COPY restent au jugement du LLM (contexte nécessaire, pas un simple
// pattern binaire).
const fromIdxAll = [];
dockerfile.split('\n').forEach((l, i) => { if (/^\s*FROM\s+\S+/i.test(l)) fromIdxAll.push(i); });
const allLines = dockerfile.split('\n');
const stageStartSec = fromIdxAll.length ? fromIdxAll[fromIdxAll.length - 1] : 0;
const finalStageLines = allLines.slice(stageStartSec);

// Ligne d'ancrage pour un finding d'ABSENCE : la dernière ligne non vide de
// l'étape finale ("ajouter après cette ligne") — jamais une ligne vide ou
// une estimation.
function lastMeaningfulLine(lines, offset) {
  for (let i = lines.length - 1; i >= 0; i--) {
    if (lines[i].trim().length > 0) return offset + i + 1;
  }
  return offset + lines.length;
}
const anchorLine = lastMeaningfulLine(finalStageLines, stageStartSec);

const securityFindings = [];

const hasUser = finalStageLines.some((l) => /^\s*USER\s+\S+/i.test(l));
if (!hasUser) {
  securityFindings.push({
    id: 'DF-SEC-USER',
    category: 'CAT-SECURITY',
    severity: 'CRITIQUE',
    ligne: anchorLine,
    description: "Absence d'instruction USER détectée par contrôle déterministe : aucune instruction USER dans l'étape finale, le conteneur s'exécute donc en tant que root par défaut.",
    suggestion: "Ajouter avant l'ENTRYPOINT/CMD : 'RUN addgroup --system appgroup && adduser --system --ingroup appgroup appuser' puis 'USER appuser'.",
    deterministic: true,
  });
}

// HEALTHCHECK NONE compte comme PRÉSENT — c'est un choix explicite de
// l'auteur, pas un oubli, jamais traité comme une absence.
const hasHealthcheck = finalStageLines.some((l) => /^\s*HEALTHCHECK\s+/i.test(l));
if (!hasHealthcheck) {
  securityFindings.push({
    id: 'DF-SEC-HEALTHCHECK',
    category: 'CAT-SECURITY',
    severity: 'ELEVE',
    ligne: anchorLine,
    description: "Absence d'instruction HEALTHCHECK détectée par contrôle déterministe : aucune instruction HEALTHCHECK dans l'étape finale, Docker/l'orchestrateur ne peut pas détecter un conteneur défaillant.",
    suggestion: "Ajouter avant l'ENTRYPOINT/CMD : 'HEALTHCHECK --interval=30s --timeout=5s --retries=3 CMD curl -f http://localhost:<port>/actuator/health || exit 1' (adapter le endpoint).",
    deterministic: true,
  });
}

// Secret en dur : ENV/ARG dont le NOM évoque un secret ET porteur d'une
// valeur littérale sur la même ligne — scanne TOUT le Dockerfile (pas
// seulement l'étape finale : une valeur en dur dans une étape builder reste
// visible dans l'historique/cache de build, donc un risque réel aussi).
const SECRET_VAR_RE = /(password|passwd|pwd|secret|token|api[_-]?key|access[_-]?key|private[_-]?key|credential)/i;
allLines.forEach((l, i) => {
  const eqForm = /^\s*(ENV|ARG)\s+([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(\S.*)$/i.exec(l);
  const spaceForm = !eqForm ? /^\s*(ENV)\s+([A-Za-z_][A-Za-z0-9_]*)\s+(\S.*)$/i.exec(l) : null;
  const m = eqForm || spaceForm;
  if (!m) return;
  const [, instr, varName, varValue] = m;
  if (!SECRET_VAR_RE.test(varName) || !varValue || !varValue.trim()) return;
  securityFindings.push({
    id: `DF-SEC-SECRET-${i + 1}`,
    category: 'CAT-SECURITY',
    severity: 'CRITIQUE',
    ligne: i + 1,
    description: `Valeur potentiellement sensible en dur détectée par contrôle déterministe : la variable "${varName}" (${instr}) est définie avec une valeur littérale directement dans le Dockerfile.`,
    suggestion: `Ne jamais écrire de secret en dur dans le Dockerfile — injecter "${varName}" au runtime (variable d'environnement du conteneur, secret manager) ou via --build-arg sans valeur par défaut sensible.`,
    deterministic: true,
  });
});

// ADD utilisé pour un fichier LOCAL simple : mauvaise pratique nette — ADD
// n'est justifié que pour une URL distante (téléchargement) ou une archive
// locale connue (extraction automatique). Scanne tout le Dockerfile (toutes
// étapes), --chown/--chmod ignorés avant la paire source/destination.
const ARCHIVE_EXT_RE = /\.(tar|tar\.gz|tgz|tar\.bz2|tbz2|tar\.xz|txz|zip)$/i;
allLines.forEach((l, i) => {
  const m = /^\s*ADD\s+(?:--\S+\s+)*(\S+)\s+\S+/i.exec(l);
  if (!m) return;
  const src = m[1];
  const isRemoteUrl = /^https?:\/\//i.test(src);
  const isKnownArchive = ARCHIVE_EXT_RE.test(src);
  if (isRemoteUrl || isKnownArchive) return; // usage légitime d'ADD, jamais signalé
  securityFindings.push({
    id: `DF-SEC-ADD-${i + 1}`,
    category: 'CAT-SECURITY',
    severity: 'FAIBLE',
    ligne: i + 1,
    description: `Utilisation d'ADD pour un fichier local détectée par contrôle déterministe : "${src}" n'est ni une URL distante ni une archive reconnue (extraction automatique) — ADD n'apporte alors aucun bénéfice par rapport à COPY, dont le comportement est strictement prévisible.`,
    suggestion: `Remplacer par COPY : le comportement d'ADD (extraction automatique, gestion des URL) n'est pas nécessaire ici et peut surprendre.`,
    deterministic: true,
  });
});

return [{
  json: {
    ...item,
    deterministicChecks: {
      runtimeCoherence: { checks: rcDetails, notes: rcNotes },
      findings: [...rcFindings, ...imageFindings, ...securityFindings],
    },
  },
}];

const body = $input.first().json.body || $input.first().json;
const dockerfile = String(body.dockerfile || '').trim();
const findings = Array.isArray(body.findings) ? body.findings : [];
const context = body.context || {};

if (!dockerfile || dockerfile.length < 20) return [{ json: { error: 'INVALID_INPUT', message: 'Dockerfile vide ou trop court (min 20 caractères)' } }];
if (dockerfile.length > 30000) return [{ json: { error: 'TOO_LARGE', message: 'Dockerfile trop volumineux (max 30 Ko)' } }];
if (findings.length === 0) return [{ json: { error: 'NOTHING_TO_APPLY', message: 'Aucun finding sélectionné : rien à appliquer' } }];

const numberLines = (text) => text.split('\n').map((l, i) => `${i + 1}: ${l}`).join('\n');
const dockerfileNumbered = numberLines(dockerfile);

return [{ json: {
  dockerfile,
