const d = $input.first().json;
const dockerfileNumbered = d.dockerfileNumbered;
const findings = Array.isArray(d.findings) ? d.findings : [];
const pomXml = d.pomXml || '';
const appConfig = d.appConfig || '';

const fmtFinding = (f) => `- [${f.id || '?'}] (${f.category || '?'}, ligne ${f.ligne ?? '?'}) ${f.description || ''}\n    → Correction attendue : ${f.suggestion || ''}`;
const fmtList = findings.length ? findings.map(fmtFinding).join('\n') : '- (aucune)';
const idsList = findings.map((f) => f.id).filter(Boolean).join(', ') || '(aucune)';

const contextBlock = (pomXml || appConfig)
  ? `\nCONTEXTE (fourni UNIQUEMENT pour comprendre certains findings — ne fait PAS partie de ta sortie, tu ne dois JAMAIS le modifier ni le recopier) :\n${pomXml ? `pom.xml :\n\`\`\`xml\n${pomXml}\n\`\`\`\n` : ''}${appConfig ? `configuration applicative :\n\`\`\`\n${appConfig}\n\`\`\`\n` : ''}`
  : '';

const systemPrompt = `Tu es un expert Docker et sécurité des conteneurs (15 ans d'expérience), spécialisé DevSecOps.
Ta mission : produire une version CORRIGÉE d'un Dockerfile en appliquant EXACTEMENT et UNIQUEMENT les corrections listées ci-dessous, sans jamais en introduire d'autres.
Réponds UNIQUEMENT en JSON valide — pas de markdown, pas de backticks. Commence par { et termine par }.
LANGUE : les textes (description) en FRANÇAIS. Les instructions Docker restent en anglais standard.

RÈGLES IMPÉRATIVES :
1. Applique SEULEMENT les corrections listées ci-dessous, une par une, à la ligne indiquée. N'en ajoute AUCUNE autre, même si tu repères d'autres problèmes en lisant le fichier — ce n'est pas ton rôle d'en juger, seules les corrections fournies sont autorisées.
2. TOUTE ligne du Dockerfile non concernée par une correction listée DOIT rester STRICTEMENT IDENTIQUE à l'original (même texte, même ordre, mêmes commentaires). Ne modifie JAMAIS sans qu'une correction listée le demande explicitement : la ligne COPY qui copie l'artefact applicatif, EXPOSE, ENTRYPOINT/CMD, WORKDIR.
3. Le fichier produit doit être COMPLET et directement utilisable — aucun "...", aucune section omise, aucune troncature.
4. N'invente RIEN de non vérifiable : n'écris JAMAIS de valeur fictive (placeholder de digest SHA256, hash inventé) ni de commande non confirmée par le contenu fourni (ex: un wrapper de build comme ./mvnw dont l'existence n'est prouvée nulle part). Si une correction ne peut être appliquée avec certitude SANS deviner une telle valeur ou commande, N'APPLIQUE PAS cette correction précise — indique-le dans changes[].description comme nécessitant une intervention manuelle, plutôt que d'inventer.
5. Si une correction nécessiterait normalement de modifier un fichier AUTRE que le Dockerfile (ex: pom.xml, application.properties), n'y touche pas : ta sortie est UNIQUEMENT le Dockerfile corrigé.

FORMAT EXACT :
{"optimizedDockerfile":"<FICHIER COMPLET>","changes":[{"ref":"<id de la correction>","description":"<modification appliquée en une phrase, ou 'non appliquée : nécessite une intervention manuelle' si applicable>"}],"confidence":<0.0-1.0>}`;

const userContent = `Voici le Dockerfile ORIGINAL à corriger.

CORRECTIONS À APPLIQUER (et rien d'autre — toute autre ligne reste identique) :
${fmtList}
${contextBlock}
DOCKERFILE ORIGINAL (numéroté, pour référence — ta sortie ne doit PAS contenir les numéros de ligne) :
\`\`\`dockerfile
${dockerfileNumbered}
\`\`\`

RAPPEL FINAL avant de répondre : seules ces corrections sont autorisées — ${idsList}. Relis le fichier que tu produis : chaque ligne modifiée ou ajoutée doit être justifiable par UNE de ces corrections précises, jamais par une initiative personnelle.`;

return [{ json: { apiBody: { model: 'claude-sonnet-4-6', max_tokens: 8000, temperature: 0, system: systemPrompt, messages: [{ role: 'user', content: userContent }] } } }];

const response = $input.first().json;
const fail = (msg, raw) => [{ json: { success: false, error: 'PARSE_ERROR', message: msg, raw: String(raw || '').substring(0, 500) } }];
if (response.error) {
  const em = response.message || (response.error && (response.error.message || (typeof response.error === 'string' ? response.error : JSON.stringify(response.error)))) || 'Erreur technique Apply Agent';
  return [{ json: { success: false, error: 'AGENT_ERROR', message: String(em) } }];
}
const content = response.content?.[0]?.text || '';
if (!content) return fail("Réponse vide de l'agent de remédiation", JSON.stringify(response).substring(0, 300));
let clean = content.replace(/```json\s*/gi, '').replace(/```\s*/gi, '').trim();
const s = clean.indexOf('{'), e = clean.lastIndexOf('}');
if (s === -1 || e === -1) return fail('Aucun JSON trouvé', clean);
let p;
try { p = JSON.parse(clean.substring(s, e + 1)); }
catch (err) { return fail('JSON invalide : ' + err.message, clean); }
if (!p.optimizedDockerfile || String(p.optimizedDockerfile).length < 20) return fail('Fichier corrigé absent ou trop court', clean);

return [{ json: {
  success: true,
  optimizedDockerfile: String(p.optimizedDockerfile),
  changes: Array.isArray(p.changes) ? p.changes : [],
  confidence: p.confidence,
} }];

const j = $input.first().json;
const em = (j.error && j.error.message) ? j.error.message : (String(j.error) || 'Erreur inconnue');
return [{ json: {
  success: false,
  error: 'AGENT_ERROR',
  message: "Agent de remédiation a échoué (rate limit / erreur API Anthropic)",
  detail: em,
} }];

const parsed = $input.first().json;

// Si Parse Apply Output a déjà échoué (JSON illisible, agent en erreur),
// rien à gater — le gate ne s'applique qu'à une sortie agent reçue.
if (!parsed.success) {
  return [{ json: { ...parsed, gateOk: false, violations: [{ family: 'PRE', message: parsed.message || 'Agent Apply en échec, gate non exécuté' }], classification: [] } }];
}

const original = String(($('Prepare - Apply Body').first().json || {}).dockerfile || '');
const findings = Array.isArray(($('Prepare - Apply Body').first().json || {}).findings) ? $('Prepare - Apply Body').first().json.findings : [];
const optimized = String(parsed.optimizedDockerfile || '');
const changes = Array.isArray(parsed.changes) ? parsed.changes : [];

const violations = [];

// ─────────────────────────────────────────────────────────────────────
// A — VALIDITÉ SYNTAXIQUE (heuristique déterministe : nécessaire, pas un
// vrai parseur Docker complet — fail-closed sur tout doute).
// ─────────────────────────────────────────────────────────────────────
const INSTR_RE = /^\s*(FROM|RUN|CMD|LABEL|EXPOSE|ENV|ADD|COPY|ENTRYPOINT|VOLUME|USER|WORKDIR|ARG|ONBUILD|STOPSIGNAL|HEALTHCHECK|SHELL)\b/i;
const optLines = optimized.split('\n');
let prevContinuation = false;
const stageNames = new Set();
optLines.forEach((line, i) => {
  const trimmed = line.trim();
  if (!trimmed || trimmed.startsWith('#')) { prevContinuation = false; return; }
  if (prevContinuation) { prevContinuation = trimmed.endsWith('\\'); return; }
  if (!INSTR_RE.test(line)) {
    violations.push({ family: 'A', message: `Ligne ${i + 1} : instruction Docker non reconnue ("${trimmed.substring(0, 60)}")` });
  }
  const fromMatch = /^\s*FROM\s+\S+\s+AS\s+(\S+)/i.exec(line);
  if (fromMatch) stageNames.add(fromMatch[1].toLowerCase());
  prevContinuation = trimmed.endsWith('\\');
});
if (!/^\s*FROM\s+\S+/im.test(optimized)) {
  violations.push({ family: 'A', message: 'Aucune instruction FROM trouvée dans le Dockerfile corrigé' });
}
optLines.forEach((line, i) => {
  const m = /COPY\s+--from=(\S+)/i.exec(line);
  if (m && !/^\d+$/.test(m[1]) && !stageNames.has(m[1].toLowerCase())) {
    violations.push({ family: 'A', message: `Ligne ${i + 1} : COPY --from="${m[1]}" référence un stage jamais déclaré (FROM ... AS ${m[1]})` });
  }
});

// ─────────────────────────────────────────────────────────────────────
// Helpers — ré-implémentent volontairement (un node Code n8n ne peut pas
// importer une fonction d'un autre node) la même logique que Runtime
// Coherence Checker / CAT-IMAGE / CAT-SECURITY. À garder synchronisé si
// ces détecteurs évoluent.
// ─────────────────────────────────────────────────────────────────────
function finalStageOf(text) {
  const lines = text.split('\n');
  const fromIdx = [];
  lines.forEach((l, i) => { if (/^\s*FROM\s+\S+/i.test(l)) fromIdx.push(i); });
  const stageStart = fromIdx.length ? fromIdx[fromIdx.length - 1] : 0;
  return { lines: lines.slice(stageStart) };
}
function extractFromTag(text) {
  const { lines } = finalStageOf(text);
  const fromLine = lines.find((l) => /^\s*FROM\s+\S+/i.test(l));
  if (!fromLine) return null;
  const ref = fromLine.replace(/^\s*FROM\s+/i, '').trim().split(/\s+/)[0];
  const after = ref.split('/').pop();
  let image = after, tag = null;
  if (after.includes(':')) { const idx = after.indexOf(':'); image = after.slice(0, idx); tag = after.slice(idx + 1); }
  const m = tag ? /^(\d+)/.exec(tag) : null;
  return { raw: ref, image, tag, majorVersion: m ? m[1] : null };
}
function hasUser(text) { return finalStageOf(text).lines.some((l) => /^\s*USER\s+\S+/i.test(l)); }
function hasHealthcheck(text) { return finalStageOf(text).lines.some((l) => /^\s*HEALTHCHECK\s+/i.test(l)); }
function extractExposePort(text) {
  const { lines } = finalStageOf(text);
  for (const l of lines) { const m = /^\s*EXPOSE\s+(\d+)/i.exec(l); if (m) return m[1]; }
  return null;
}
function extractCopyJar(text) {
  const { lines } = finalStageOf(text);
  let found = null;
  lines.forEach((l) => { if (/^\s*COPY\s+/i.test(l) && /\.jar(\s|$)/i.test(l)) found = l.trim(); });
  return found;
}
function extractEntrypointOrCmd(text) {
  const m = /^\s*(ENTRYPOINT|CMD)\s+.+$/im.exec(text);
  return m ? m[0].trim() : null;
}

// ─────────────────────────────────────────────────────────────────────
// B — CORRECTIONS PRÉSENTES (uniquement les findings ayant un détecteur
// déterministe rejouable) + D — CLASSIFICATION DE CONFIANCE.
// ─────────────────────────────────────────────────────────────────────
const classification = [];
const optFrom = extractFromTag(optimized);
const DETERMINISTIC_IDS = new Set(['DF-IMG-JDK', 'DF-IMG-PIN', 'DF-SEC-USER', 'DF-SEC-HEALTHCHECK']);

for (const f of findings) {
  const id = f.id || f.ref || '?';
  const change = changes.find((c) => c.ref === id);
  const declinedByAgent = change && /non appliqu|intervention manuelle|revue manuelle/i.test(change.description || '');

  if (declinedByAgent) {
    classification.push({ id, status: 'REFUSÉ', reason: change.description });
    continue;
  }

  if (id === 'DF-IMG-JDK') {
    // Propriété, pas une liste d'exclusion : le stage final doit être sur
    // une version LTS supportée (>=17), pas juste "hors de {6,7,8}" — une
    // version 9-16 (non-LTS, non obsolète au sens strict) ne doit PAS passer
    // ce contrôle non plus.
    const v = optFrom && optFrom.majorVersion ? parseInt(optFrom.majorVersion, 10) : NaN;
    const ok = Number.isInteger(v) && v >= 17;
    if (ok) classification.push({ id, status: 'SÛR', reason: `FROM du stage final = ${optFrom.raw} (Java ${v}, >= 17 LTS)` });
    else { classification.push({ id, status: 'MANQUANT', reason: `FROM du stage final = ${optFrom ? optFrom.raw : '?'} — pas une version LTS >= 17 (ou indéterminable)` }); violations.push({ family: 'B', ref: id, message: `Correction ${id} absente : le stage final n'est pas sur une version Java >= 17 LTS` }); }
    continue;
  }
  if (id === 'DF-IMG-PIN') {
    const ok = !!(optFrom && optFrom.tag && optFrom.tag !== 'latest');
    if (ok) classification.push({ id, status: 'SÛR', reason: `FROM final pinné sur le tag "${optFrom.tag}"` });
    else { classification.push({ id, status: 'MANQUANT', reason: 'FROM final toujours non pinné' }); violations.push({ family: 'B', ref: id, message: `Correction ${id} absente : image toujours non pinnée` }); }
    continue;
  }
  if (id === 'DF-SEC-USER') {
    const ok = hasUser(optimized);
    if (ok) classification.push({ id, status: 'SÛR', reason: "USER présent dans l'étape finale" });
    else { classification.push({ id, status: 'MANQUANT', reason: 'USER toujours absent' }); violations.push({ family: 'B', ref: id, message: `Correction ${id} absente : USER non-root toujours manquant` }); }
    continue;
  }
  if (id === 'DF-SEC-HEALTHCHECK') {
    const ok = hasHealthcheck(optimized);
    if (ok) classification.push({ id, status: 'SÛR', reason: "HEALTHCHECK présent dans l'étape finale" });
    else { classification.push({ id, status: 'MANQUANT', reason: 'HEALTHCHECK toujours absent' }); violations.push({ family: 'B', ref: id, message: `Correction ${id} absente : HEALTHCHECK toujours manquant` }); }
    continue;
  }

  // Pas de détecteur déterministe rejouable (jugement LLM : JDK-vs-JRE,
  // digest, multi-stage, RC-1/2/3, apt-get, ADD subtil...) — jamais gaté
  // sur B, seulement classé pour revue humaine.
  if (change) classification.push({ id, status: 'INFÉRÉ', reason: change.description || 'Appliqué par jugement LLM, non re-vérifiable par du code' });
  else classification.push({ id, status: 'MANQUANT', reason: "Ni appliqué ni signalé comme écarté par l'agent" });
}

// ─────────────────────────────────────────────────────────────────────
// C — RIEN CASSÉ (comparaison original vs corrigé sur les instructions
// essentielles). REJET si une instruction essentielle a disparu.
// ─────────────────────────────────────────────────────────────────────
const origExpose = extractExposePort(original);
const optExpose = extractExposePort(optimized);
if (origExpose && !optExpose) violations.push({ family: 'C', message: `EXPOSE ${origExpose} (présent dans l'original) a disparu du Dockerfile corrigé` });

const origCopyJar = extractCopyJar(original);
const optCopyJar = extractCopyJar(optimized);
if (origCopyJar && !optCopyJar) violations.push({ family: 'C', message: `Le COPY de l'artefact .jar ("${origCopyJar}") a disparu du Dockerfile corrigé` });

const origEntry = extractEntrypointOrCmd(original);
const optEntry = extractEntrypointOrCmd(optimized);
if (origEntry && !optEntry) violations.push({ family: 'C', message: `ENTRYPOINT/CMD ("${origEntry}") a disparu du Dockerfile corrigé` });
else if (origEntry && optEntry && origEntry !== optEntry) violations.push({ family: 'C', message: `ENTRYPOINT/CMD modifié sans qu'aucune correction ne le justifie : "${origEntry}" → "${optEntry}"` });

const gateOk = violations.length === 0;

return [{ json: {
  ...parsed,
  gateOk,
  violations,
  classification,
} }];
